183	static const char *
184	parse_define_directive(const char *directive, BUILD_TABLE_INFO *bti, char *errbuf, size_t errbufsize)
185	{
186	  bool             flg;
187	  acl_filter_rule *rp;
188	  const char      *cstr = nullptr;
189	
190	  if (bti->paramc < 2) {
191	    snprintf(errbuf, errbufsize, "Directive \"%s\" must have name argument", directive);
192	    Dbg(dbg_ctl_url_rewrite, "[parse_directive] %s", errbuf);
193	    return errbuf;
194	  }
195	  if (bti->argc < 1) {
196	    snprintf(errbuf, errbufsize, "Directive \"%s\" must have filter parameter(s)", directive);
197	    Dbg(dbg_ctl_url_rewrite, "[parse_directive] %s", errbuf);
198	    return errbuf;
199	  }
200	
201	  flg = ((rp = acl_filter_rule::find_byname(bti->rules_list, bti->paramv[1])) == nullptr) ? true : false;
202	  // coverity[alloc_arg]
203	  if ((cstr = remap_validate_filter_args(&rp, bti->argv, bti->argc, errbuf, errbufsize, bti->behavior_policy)) == nullptr && rp) {
204	    if (flg) { // new filter - add to list
205	      acl_filter_rule **rpp = nullptr;
206	      Dbg(dbg_ctl_url_rewrite, "[parse_directive] new rule \"%s\" was created", bti->paramv[1]);
207	      for (rpp = &bti->rules_list; *rpp; rpp = &((*rpp)->next)) {
208	        ;
209	      }
210	      (*rpp = rp)->name(bti->paramv[1]);
211	    }
212	    Dbg(dbg_ctl_url_rewrite, "[parse_directive] %d argument(s) were added to rule \"%s\"", bti->argc, bti->paramv[1]);
213	    rp->add_argv(bti->argc, bti->argv); // store string arguments for future processing
214	  }
215	
216	  return cstr;
217	}
