109	acl_filter_rule::print()
110	{
111	  int i;
112	  printf("-----------------------------------------------------------------------------------------\n");
113	  printf(
114	    "Filter \"%s\" status: allow_flag=%s, add_flag=%s, src_ip_valid=%s, src_ip_category_valid=%s, in_ip_valid=%s, internal=%s, "
115	    "active_queue_flag=%d\n",
116	    filter_name ? filter_name : "<NONAME>", allow_flag ? "true" : "false", add_flag ? "true" : "false",
117	    src_ip_valid ? "true" : "false", src_ip_category_valid ? "true" : "false", in_ip_valid ? "true" : "false",
118	    internal ? "true" : "false", static_cast<int>(active_queue_flag));
119	  printf("standard methods=");
120	  for (i = 0; i < HTTP_WKSIDX_METHODS_CNT; i++) {
121	    if (standard_method_lookup[i]) {
122	      printf("0x%x ", HTTP_WKSIDX_CONNECT + i);
123	    }
124	  }
125	  printf("\n");
126	  printf("nonstandard methods=");
127	  for (const auto &nonstandard_method : nonstandard_methods) {
128	    printf("%s ", nonstandard_method.c_str());
129	  }
130	  printf("\n");
131	  printf("src_ip_cnt=%d\n", src_ip_cnt);
132	  for (i = 0; i < src_ip_cnt; i++) {
